import {globalIdField} from './core.js?v=20261015-template';
export function trackingField(meta,role='creator'){const name=meta.editFieldsInfo?.[role==='editor'?'editorField':'creatorField'];if(!name||!meta.fields?.some(f=>f.name===name))throw Error('This layer does not expose the selected '+role+' tracking field.');return name;}
export function surveyUsers(meta,features,role){const name=trackingField(meta,role);return [...new Set(features.map(f=>f.attributes[name]).filter(v=>typeof v==='string'&&v.trim()))].sort();}
export function missingKind(value){return value==null?'NULL':typeof value==='string'&&value.trim()===''?'Blank':'';}
export function surveyIssues(url,meta,features,role,users,required){const tracking=trackingField(meta,role),gid=globalIdField(meta),selected=new Set(users);const fields=required.map(name=>{const field=meta.fields.find(f=>f.name===name);if(!field)throw Error('Required field no longer exists: '+name);return field;});const issues=[];for(const f of features){const attrs=f.attributes,user=attrs[tracking];if(!selected.has(user))continue;for(const field of fields){const kind=missingKind(attrs[field.name]);if(kind){const id=attrs[gid?.name]||attrs[meta.objectIdField];issues.push({key:JSON.stringify([url,id,field.name,user]),layer:meta.name,url,user,id,field:field.name,kind});}}}return issues;}
export function newSurveyIssues(issues,previous){return issues.filter(issue=>!previous.has(issue.key));}
